  localparam logic [31:0] LPARA_QSPI_CMD_OFFSET = 32'h0014,
  localparam logic [31:0] LPARA_QSPI_ADDR_OFFSET = 32'h0018,
  localparam logic [31:0] LPARA_QSPI_LEN_OFFSET = 32'h001c,
  localparam logic [31:0] LPARA_QSPI_STS_OFFSET = 32'h0020,
