  localparam logic [31:0] LPARA_QSPI_IRQ_EN_OFFSET = 32'h0028,
  localparam logic [31:0] LPARA_QSPI_IRQ_INJ_OFFSET = 32'h002c,
  localparam logic [31:0] LPARA_QSPI_IRQ_STS_OFFSET = 32'h0030,
  localparam logic [31:0] LPARA_QSPI_CS_CFG_OFFSET = 32'h0034
) (
  // APB clock and reset
  input  wire                     i_clk_apb,
  input  wire                     i_rst_n_apb,

  // Register clock and reset (used only in asynchronous mode)
  input  wire                     i_clk_reg,
  input  wire                     i_rst_n_reg,

  // APB slave interface
  input  wire                     i_apb_psel,
  input  wire                     i_apb_penable,
