  // Register qspi_ctrl
  output logic                    o_qspi_ctrl_lsb_first,
  output logic                    o_qspi_ctrl_cpha,
  output logic                    o_qspi_ctrl_cpol,
  output logic                    o_qspi_ctrl_role,
  output logic                    o_qspi_ctrl_en,

  // Register qspi_clkdiv
  output logic [15:0]             o_qspi_clkdiv_divisor,

  // Register qspi_frame
  output logic [5:0]              o_qspi_frame_word_len_m1,

  // Register qspi_xip_cfg
  output logic [7:0]              o_qspi_xip_cfg_dummy_cyc,
  output logic [2:0]              o_qspi_xip_cfg_format,
  output logic [1:0]              o_qspi_xip_cfg_addr_bytes,
  output logic [7:0]              o_qspi_xip_cfg_opcode,
  output logic                    o_qspi_xip_cfg_en,

  // Register qspi_xip_mode
  output logic [4:0]              o_qspi_xip_mode_mode_count,
  output logic [7:0]              o_qspi_xip_mode_mode_value,

  // Register qspi_cmd
  output logic                    o_qspi_cmd_start,
  input  wire                     i_hw_wdata_qspi_cmd_start,
  input  wire                     i_hw_we_qspi_cmd_start,
  output logic                    o_qspi_cmd_rd,
  output logic [7:0]              o_qspi_cmd_dummy_cyc,
  output logic [1:0]              o_qspi_cmd_addr_bytes,
