  // Register qspi_irq_raw
  output logic                    o_qspi_irq_raw_fl_err,
  input  wire                     i_hw_wdata_qspi_irq_raw_fl_err,
  input  wire                     i_hw_we_qspi_irq_raw_fl_err,
  output logic                    o_qspi_irq_raw_rx_err,
  input  wire                     i_hw_wdata_qspi_irq_raw_rx_err,
  input  wire                     i_hw_we_qspi_irq_raw_rx_err,
  output logic                    o_qspi_irq_raw_tx_err,
  input  wire                     i_hw_wdata_qspi_irq_raw_tx_err,
  input  wire                     i_hw_we_qspi_irq_raw_tx_err,
  output logic                    o_qspi_irq_raw_done,
  input  wire                     i_hw_wdata_qspi_irq_raw_done,
  input  wire                     i_hw_we_qspi_irq_raw_done,

  // Register qspi_irq_en
