  output logic                    o_qspi_irq_en_rx_err,
  output logic                    o_qspi_irq_en_tx_err,
  output logic                    o_qspi_irq_en_done,

  // Register qspi_irq_inj
  output logic                    o_qspi_irq_inj_fl_err,
  output logic                    o_qspi_irq_inj_rx_err,
  output logic                    o_qspi_irq_inj_tx_err,
  output logic                    o_qspi_irq_inj_done,

  // Register qspi_irq_sts
  input  wire                     i_qspi_irq_sts_fl_err,
  input  wire                     i_qspi_irq_sts_rx_err,
  input  wire                     i_qspi_irq_sts_tx_err,
  input  wire                     i_qspi_irq_sts_done,

  // Register qspi_cs_cfg
  output logic [7:0]              o_qspi_cs_cfg_cs_high,
  output logic [7:0]              o_qspi_cs_cfg_cs_hold,
  output logic [7:0]              o_qspi_cs_cfg_cs_setup,
  output logic [3:0]              o_qspi_cs_cfg_cs_sel
);

  // Internal signal declarations
  logic w_apb_setup;
  logic w_apb_prot_ok;
  logic w_apb_slverr;
  logic w_apb_complete;
  logic w_apb_wr;
  logic w_apb_rd;
  logic [LPARA_ADDR_W-1:0] reg_addr;
  logic [LPARA_DATA_W-1:0] reg_wdata;
  logic reg_slverr;
  logic w_rd_en;
  logic w_wr_en;
  logic w_rd_ack_fall;
  logic [LPARA_DATA_W-1:0] w_rdata_nxt;
  logic [LPARA_DATA_W-1:0] reg_rdata;
  logic w_clk_reg;
  logic w_rst_n_reg;
  logic w_we_qspi_ctrl;
  logic reg_qspi_ctrl_lsb_first;
  logic w_qspi_ctrl_lsb_first_nxt;
  logic reg_qspi_ctrl_cpha;
  logic w_qspi_ctrl_cpha_nxt;
  logic reg_qspi_ctrl_cpol;
  logic w_qspi_ctrl_cpol_nxt;
  logic reg_qspi_ctrl_role;
  logic w_qspi_ctrl_role_nxt;
  logic reg_qspi_ctrl_en;
  logic w_qspi_ctrl_en_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_ctrl_value;
  logic w_we_qspi_clkdiv;
  logic [15:0] reg_qspi_clkdiv_divisor;
  logic [15:0] w_qspi_clkdiv_divisor_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_clkdiv_value;
  logic w_we_qspi_frame;
  logic [5:0] reg_qspi_frame_word_len_m1;
  logic [5:0] w_qspi_frame_word_len_m1_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_frame_value;
  logic w_we_qspi_xip_cfg;
  logic [7:0] reg_qspi_xip_cfg_dummy_cyc;
  logic [7:0] w_qspi_xip_cfg_dummy_cyc_nxt;
  logic [2:0] reg_qspi_xip_cfg_format;
  logic [2:0] w_qspi_xip_cfg_format_nxt;
  logic [1:0] reg_qspi_xip_cfg_addr_bytes;
  logic [1:0] w_qspi_xip_cfg_addr_bytes_nxt;
  logic [7:0] reg_qspi_xip_cfg_opcode;
  logic [7:0] w_qspi_xip_cfg_opcode_nxt;
  logic reg_qspi_xip_cfg_en;
  logic w_qspi_xip_cfg_en_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_xip_cfg_value;
  logic w_we_qspi_xip_mode;
  logic [4:0] reg_qspi_xip_mode_mode_count;
  logic [4:0] w_qspi_xip_mode_mode_count_nxt;
  logic [7:0] reg_qspi_xip_mode_mode_value;
  logic [7:0] w_qspi_xip_mode_mode_value_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_xip_mode_value;
  logic w_we_qspi_cmd;
  logic reg_qspi_cmd_start;
  logic w_qspi_cmd_start_nxt;
  logic reg_qspi_cmd_rd;
  logic w_qspi_cmd_rd_nxt;
  logic [7:0] reg_qspi_cmd_dummy_cyc;
  logic [7:0] w_qspi_cmd_dummy_cyc_nxt;
  logic [1:0] reg_qspi_cmd_addr_bytes;
  logic [1:0] w_qspi_cmd_addr_bytes_nxt;
  logic [2:0] reg_qspi_cmd_format;
  logic [2:0] w_qspi_cmd_format_nxt;
  logic [7:0] reg_qspi_cmd_opcode;
  logic [7:0] w_qspi_cmd_opcode_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_cmd_value;
  logic w_we_qspi_addr;
  logic [31:0] reg_qspi_addr_addr;
  logic [31:0] w_qspi_addr_addr_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_addr_value;
  logic w_we_qspi_len;
  logic [15:0] reg_qspi_len_byte_count;
  logic [15:0] w_qspi_len_byte_count_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_len_value;
  logic [LPARA_DATA_W-1:0] w_qspi_sts_value;
  logic w_we_qspi_irq_raw;
  logic reg_qspi_irq_raw_fl_err;
  logic w_qspi_irq_raw_fl_err_nxt;
  logic reg_qspi_irq_raw_rx_err;
  logic w_qspi_irq_raw_rx_err_nxt;
  logic reg_qspi_irq_raw_tx_err;
  logic w_qspi_irq_raw_tx_err_nxt;
  logic reg_qspi_irq_raw_done;
  logic w_qspi_irq_raw_done_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_irq_raw_value;
  logic w_we_qspi_irq_en;
  logic reg_qspi_irq_en_fl_err;
  logic w_qspi_irq_en_fl_err_nxt;
  logic reg_qspi_irq_en_rx_err;
  logic w_qspi_irq_en_rx_err_nxt;
  logic reg_qspi_irq_en_tx_err;
  logic w_qspi_irq_en_tx_err_nxt;
  logic reg_qspi_irq_en_done;
  logic w_qspi_irq_en_done_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_irq_en_value;
  logic w_we_qspi_irq_inj;
  logic reg_qspi_irq_inj_fl_err;
  logic w_qspi_irq_inj_fl_err_nxt;
  logic reg_qspi_irq_inj_rx_err;
  logic w_qspi_irq_inj_rx_err_nxt;
  logic reg_qspi_irq_inj_tx_err;
  logic w_qspi_irq_inj_tx_err_nxt;
  logic reg_qspi_irq_inj_done;
  logic w_qspi_irq_inj_done_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_irq_inj_value;
  logic [LPARA_DATA_W-1:0] w_qspi_irq_sts_value;
  logic w_we_qspi_cs_cfg;
  logic [7:0] reg_qspi_cs_cfg_cs_high;
  logic [7:0] w_qspi_cs_cfg_cs_high_nxt;
  logic [7:0] reg_qspi_cs_cfg_cs_hold;
  logic [7:0] w_qspi_cs_cfg_cs_hold_nxt;
  logic [7:0] reg_qspi_cs_cfg_cs_setup;
  logic [7:0] w_qspi_cs_cfg_cs_setup_nxt;
  logic [3:0] reg_qspi_cs_cfg_cs_sel;
  logic [3:0] w_qspi_cs_cfg_cs_sel_nxt;
  logic [LPARA_DATA_W-1:0] w_qspi_cs_cfg_value;

  // The parameter is constant at elaboration, so this selects a clock without a runtime mux.
  assign w_clk_reg   = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;

  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_qspi_ctrl = w_wr_en & (reg_addr == LPARA_QSPI_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_clkdiv = w_wr_en & (reg_addr == LPARA_QSPI_CLKDIV_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_frame = w_wr_en & (reg_addr == LPARA_QSPI_FRAME_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_xip_cfg = w_wr_en & (reg_addr == LPARA_QSPI_XIP_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_xip_mode = w_wr_en & (reg_addr == LPARA_QSPI_XIP_MODE_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_cmd = w_wr_en & (reg_addr == LPARA_QSPI_CMD_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_addr = w_wr_en & (reg_addr == LPARA_QSPI_ADDR_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_len = w_wr_en & (reg_addr == LPARA_QSPI_LEN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_irq_raw = w_wr_en & (reg_addr == LPARA_QSPI_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_irq_en = w_wr_en & (reg_addr == LPARA_QSPI_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_irq_inj = w_wr_en & (reg_addr == LPARA_QSPI_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_qspi_cs_cfg = w_wr_en & (reg_addr == LPARA_QSPI_CS_CFG_OFFSET[LPARA_ADDR_W-1:0]);

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
        if (!i_rst_n_reg)
          reg_rd_req_reg_dly <= 1'b0;
        else
          reg_rd_req_reg_dly <= w_rd_req_reg;
      end
      assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
      assign w_rd_ack = reg_rd_req_reg_dly;

      // Write request is synchronized into the register clock domain.
      m_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_wr_req),
        .o_q         (w_wr_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
          reg_wr_req_reg_dly <= w_wr_req_reg;
      end
      assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
      assign w_wr_ack = reg_wr_req_reg_dly;

      // PREADY pulses after an acknowledged operation or a SETUP-phase error.
      assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end else begin : g_sync_csr

      // Synchronous-only request capture and response state.
      logic reg_rd_capture;
      logic reg_wr_capture;
      logic w_pready_nxt;
      logic reg_pready;

      // Read/write enables are delayed one cycle in synchronous mode.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_capture
        if (!i_rst_n_apb) begin
          reg_rd_capture <= 1'b0;
          reg_wr_capture <= 1'b0;
        end else begin
          reg_rd_capture <= w_apb_rd;
          reg_wr_capture <= w_apb_wr;
        end
      end
      assign w_rd_en = reg_rd_capture;
