  // qspi_irq_inj_done next value (rw): a software write loads it, otherwise hold.
  assign w_qspi_irq_inj_done_nxt = (w_we_qspi_irq_inj) ? reg_wdata[0] : reg_qspi_irq_inj_done;

  // Register qspi_irq_inj: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_qspi_irq_inj
    if (!w_rst_n_reg) begin
      reg_qspi_irq_inj_fl_err <= 1'h0;
      reg_qspi_irq_inj_rx_err <= 1'h0;
      reg_qspi_irq_inj_tx_err <= 1'h0;
      reg_qspi_irq_inj_done <= 1'h0;
    end else begin
      reg_qspi_irq_inj_fl_err <= w_qspi_irq_inj_fl_err_nxt;
      reg_qspi_irq_inj_rx_err <= w_qspi_irq_inj_rx_err_nxt;
      reg_qspi_irq_inj_tx_err <= w_qspi_irq_inj_tx_err_nxt;
      reg_qspi_irq_inj_done <= w_qspi_irq_inj_done_nxt;
    end
  end

  // Register qspi_irq_inj: output ports follow the flops.
  assign o_qspi_irq_inj_fl_err = reg_qspi_irq_inj_fl_err;
  assign o_qspi_irq_inj_rx_err = reg_qspi_irq_inj_rx_err;
  assign o_qspi_irq_inj_tx_err = reg_qspi_irq_inj_tx_err;
  assign o_qspi_irq_inj_done = reg_qspi_irq_inj_done;

  // Register qspi_irq_inj: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_qspi_irq_inj_value
    w_qspi_irq_inj_value = '0;
    w_qspi_irq_inj_value[3] = reg_qspi_irq_inj_fl_err;
    w_qspi_irq_inj_value[2] = reg_qspi_irq_inj_rx_err;
    w_qspi_irq_inj_value[1] = reg_qspi_irq_inj_tx_err;
    w_qspi_irq_inj_value[0] = reg_qspi_irq_inj_done;
  end

  // Register qspi_irq_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_qspi_irq_sts_value
    w_qspi_irq_sts_value = '0;
    w_qspi_irq_sts_value[3] = i_qspi_irq_sts_fl_err;
    w_qspi_irq_sts_value[2] = i_qspi_irq_sts_rx_err;
    w_qspi_irq_sts_value[1] = i_qspi_irq_sts_tx_err;
    w_qspi_irq_sts_value[0] = i_qspi_irq_sts_done;
  end

  // qspi_cs_cfg_cs_high next value (rw): a software write loads it, otherwise hold.
  assign w_qspi_cs_cfg_cs_high_nxt = (w_we_qspi_cs_cfg) ? reg_wdata[27:20] : reg_qspi_cs_cfg_cs_high;

  // qspi_cs_cfg_cs_hold next value (rw): a software write loads it, otherwise hold.
  assign w_qspi_cs_cfg_cs_hold_nxt = (w_we_qspi_cs_cfg) ? reg_wdata[19:12] : reg_qspi_cs_cfg_cs_hold;

  // qspi_cs_cfg_cs_setup next value (rw): a software write loads it, otherwise hold.
  assign w_qspi_cs_cfg_cs_setup_nxt = (w_we_qspi_cs_cfg) ? reg_wdata[11:4] : reg_qspi_cs_cfg_cs_setup;

  // qspi_cs_cfg_cs_sel next value (rw): a software write loads it, otherwise hold.
  assign w_qspi_cs_cfg_cs_sel_nxt = (w_we_qspi_cs_cfg) ? reg_wdata[3:0] : reg_qspi_cs_cfg_cs_sel;

  // Register qspi_cs_cfg: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_qspi_cs_cfg
    if (!w_rst_n_reg) begin
      reg_qspi_cs_cfg_cs_high <= 8'h0;
      reg_qspi_cs_cfg_cs_hold <= 8'h0;
      reg_qspi_cs_cfg_cs_setup <= 8'h0;
      reg_qspi_cs_cfg_cs_sel <= 4'h0;
    end else begin
      reg_qspi_cs_cfg_cs_high <= w_qspi_cs_cfg_cs_high_nxt;
      reg_qspi_cs_cfg_cs_hold <= w_qspi_cs_cfg_cs_hold_nxt;
      reg_qspi_cs_cfg_cs_setup <= w_qspi_cs_cfg_cs_setup_nxt;
      reg_qspi_cs_cfg_cs_sel <= w_qspi_cs_cfg_cs_sel_nxt;
    end
  end

  // Register qspi_cs_cfg: output ports follow the flops.
  assign o_qspi_cs_cfg_cs_high = reg_qspi_cs_cfg_cs_high;
  assign o_qspi_cs_cfg_cs_hold = reg_qspi_cs_cfg_cs_hold;
  assign o_qspi_cs_cfg_cs_setup = reg_qspi_cs_cfg_cs_setup;
  assign o_qspi_cs_cfg_cs_sel = reg_qspi_cs_cfg_cs_sel;

  // Register qspi_cs_cfg: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_qspi_cs_cfg_value
    w_qspi_cs_cfg_value = '0;
    w_qspi_cs_cfg_value[27:20] = reg_qspi_cs_cfg_cs_high;
    w_qspi_cs_cfg_value[19:12] = reg_qspi_cs_cfg_cs_hold;
    w_qspi_cs_cfg_value[11:4] = reg_qspi_cs_cfg_cs_setup;
    w_qspi_cs_cfg_value[3:0] = reg_qspi_cs_cfg_cs_sel;
  end

  // Read data mux returns zero for addresses that do not map to a register.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (32'(reg_addr))
      LPARA_QSPI_CTRL_OFFSET: w_rdata_nxt = w_qspi_ctrl_value;
      LPARA_QSPI_CLKDIV_OFFSET: w_rdata_nxt = w_qspi_clkdiv_value;
      LPARA_QSPI_FRAME_OFFSET: w_rdata_nxt = w_qspi_frame_value;
      LPARA_QSPI_XIP_CFG_OFFSET: w_rdata_nxt = w_qspi_xip_cfg_value;
      LPARA_QSPI_XIP_MODE_OFFSET: w_rdata_nxt = w_qspi_xip_mode_value;
      LPARA_QSPI_CMD_OFFSET: w_rdata_nxt = w_qspi_cmd_value;
      LPARA_QSPI_ADDR_OFFSET: w_rdata_nxt = w_qspi_addr_value;
      LPARA_QSPI_LEN_OFFSET: w_rdata_nxt = w_qspi_len_value;
      LPARA_QSPI_STS_OFFSET: w_rdata_nxt = w_qspi_sts_value;
      LPARA_QSPI_IRQ_RAW_OFFSET: w_rdata_nxt = w_qspi_irq_raw_value;
      LPARA_QSPI_IRQ_EN_OFFSET: w_rdata_nxt = w_qspi_irq_en_value;
      LPARA_QSPI_IRQ_INJ_OFFSET: w_rdata_nxt = w_qspi_irq_inj_value;
      LPARA_QSPI_IRQ_STS_OFFSET: w_rdata_nxt = w_qspi_irq_sts_value;
      LPARA_QSPI_CS_CFG_OFFSET: w_rdata_nxt = w_qspi_cs_cfg_value;
      default: begin
        w_rdata_nxt = '0;
      end
    endcase
  end

  // Read response storage follows the selected clock architecture.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_rdata
      logic [LPARA_DATA_W-1:0] reg_rdata_bus;

      // Snapshot read data in the register clock domain.
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
        if (!i_rst_n_reg)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end

      // The synchronized acknowledge qualifies the stable bundled read data.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
        if (!i_rst_n_apb)
          reg_rdata_bus <= '0;
        else if (w_rd_ack_fall)
          reg_rdata_bus <= reg_rdata;
      end
      assign o_apb_prdata = reg_rdata_bus;
    end else begin : g_sync_rdata
      // Synchronous read data is captured in the APB/register clock domain.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
        if (!i_rst_n_apb)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end
      assign o_apb_prdata = reg_rdata;
    end
  endgenerate

endmodule
